/**
 * The release roster, as a committed snapshot of downloads.myne.md.
 *
 * ── Where the values come from ─────────────────────────────────────────────
 *
 * `releases.json` next to this file is generated by `scripts/sync-releases.mjs`
 * from the origin's `releases/index.json`, which is signed by the offline
 * release key. The script verifies that signature with `minisign` before it
 * writes a single byte, and refuses to write otherwise. Nothing here is typed
 * by hand any more: the file this replaces held ONE release and had drifted a
 * version behind the origin, so the page that exists to witness releases was
 * witnessing the wrong one.
 *
 * ── Why the page does not fetch it at runtime ─────────────────────────────
 *
 * This is the second witness, and it only works because it is a *different*
 * one: these bytes ship from `myne-website`, through its own Woodpecker chain,
 * onto `myne.md`. The artefacts ship from `operations`, by hand, onto the status
 * box. Fetching hashes at runtime would collapse that: a compromised downloads
 * origin would then be supplying both the binary and the hash a reader checks
 * it against. So the snapshot is committed, the page renders plain <a href>
 * links, and there is no CORS anywhere in it.
 *
 * ── What a signature does and does not prove ───────────────────────────────
 *
 * It proves the hash LIST is ours. It does not prove the published bytes were
 * built from the published source; that is A9's residual
 * (`docs/threat-model.md`), and `stage-release.sh` is what checks artefacts
 * against the release itself.
 *
 * ── Updating ───────────────────────────────────────────────────────────────
 *
 *   node scripts/sync-releases.mjs && node scripts/validate-release.mjs
 *
 * then read the diff and commit it. `sync-releases.mjs --check` exits non-zero
 * when the committed snapshot no longer matches the origin, which is what a
 * release pass should notice.
 */
import snapshot from "./releases.json";

export interface ReleaseAsset {
  /** File name, exactly as it appears in SHA256SUMS. */
  name: string;
  bytes: number;
  sha256: string;
}

export interface Release {
  tag: string;
  version: string;
  date: string;
  assets: ReleaseAsset[];
}

export const DOWNLOADS_ORIGIN: string = snapshot.origin;

/**
 * Public halves of the offline release-signing keys. They sign SHA256SUMS and
 * the release index, NOT the installers.
 *
 * The key rotated on 2026-10-03: the previous key was held only on a machine no
 * longer used to sign, so a new one was minted (no compromise is implied). Both
 * are published in three places on purpose (here, security.txt, and the
 * origin's own index.json) so a reader who distrusts one origin can compare.
 * Releases at or after v0.9.0 verify against the first key; earlier releases
 * against the second. `minisign -Vm SHA256SUMS -P <key>` takes one key at a time.
 */
export const MINISIGN_PUBKEY: string = snapshot.pubkey;
export const MINISIGN_PUBKEYS: string[] = snapshot.pubkeys;

/**
 * Which release each channel points at, taken from the origin's own updater
 * manifests (`latest.json` and `latest-beta.json`). They answer the same
 * question the app's updater asks, which is the point: a page that invented its
 * own notion of "latest" would disagree with the client.
 */
export const CHANNELS: { stable: string; beta: string } = snapshot.channels;

/** Newest first. */
export const RELEASES: Release[] = snapshot.releases;

export function releaseByTag(tag: string): Release | undefined {
  return RELEASES.find((r) => r.tag === tag);
}

function requireRelease(tag: string, label: string): Release {
  const found = releaseByTag(tag);
  if (!found) {
    throw new Error(
      `release.ts: ${label} channel points at ${tag}, which is not in the roster`,
    );
  }
  return found;
}

/** The release the stable channel points at. */
export const STABLE = requireRelease(CHANNELS.stable, "stable");
/** The release the beta channel points at. */
export const BETA = requireRelease(CHANNELS.beta, "beta");
/** True while the two channels publish the same build, which is the normal
 *  state between releases rather than an error. */
export const CHANNELS_MATCH = STABLE.tag === BETA.tag;

/** Kept for the badge and the OG image, which name the current version. */
export const RELEASE_TAG = STABLE.tag;
export const RELEASE_VERSION = STABLE.version;
export const RELEASE_DATE = STABLE.date;

export function assetUrl(name: string, tag: string = RELEASE_TAG): string {
  return `${DOWNLOADS_ORIGIN}/releases/${tag}/${name}`;
}

/** The checksum list for a release, which a reader downloads to verify. */
export function checksumsUrl(tag: string = RELEASE_TAG): string {
  return assetUrl("SHA256SUMS", tag);
}

export function signatureUrl(tag: string = RELEASE_TAG): string {
  return assetUrl("SHA256SUMS.minisig", tag);
}

/** The origin's own directory for a release: what a human browses when the
 *  page lacks the artefact they want. */
export function releaseDirUrl(tag: string = RELEASE_TAG): string {
  return `${DOWNLOADS_ORIGIN}/releases/${tag}/`;
}

export function assetByName(name: string, tag: string = RELEASE_TAG): ReleaseAsset {
  const release = requireRelease(tag, "requested");
  const found = release.assets.find((a) => a.name === name);
  // A typo'd file name would otherwise render a link that 404s, silently, on a
  // page whose whole job is handing people a working installer.
  if (!found) throw new Error(`release.ts: ${tag} has no asset named ${name}`);
  return found;
}

/** "512 MB" — what a person reads before clicking a half-gigabyte link. */
export function humanSize(bytes: number): string {
  return `${Math.round(bytes / 1_000_000)} MB`;
}

/** "14 October 2026" — a release date is a fact about the file, and an ISO
 *  string reads as a build stamp to everyone who is not a machine. */
export function humanDate(iso: string): string {
  const [y, m, d] = iso.split("-").map(Number);
  const months = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
  ];
  return `${d} ${months[m - 1]} ${y}`;
}
